flowDot:
digraph G {
  rankdir=TB; bgcolor="transparent"; nodesep=0.35; ranksep=0.5; newrank=true;
  node [fontname="Helvetica", fontsize=18, margin="0.2,0.1", style="rounded,filled", penwidth=2];
  edge [fontname="Helvetica", fontsize=16, penwidth=1.5, color="#6B7280"];
  START [label="Returning to\nearlier work", shape=box, style="rounded,filled", fillcolor="#EDE9FE", color="#7C3AED"];
  Q [label="What's still true\nsince then?", shape=diamond, style="rounded,filled", fillcolor="#EDE9FE", color="#7C3AED"];
  NAMED [label="⭐ nothing changed\n→ --resume <name>", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  TELL [label="⭐ a few files changed\n→ resume + name the files\n(targeted re-read)", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  FRESH [label="⭐ most results stale\n→ new session +\nstructured summary", shape=box, style="rounded,filled", fillcolor="#FEF3C7", color="#D97706"];
  FORK [label="⭐ explore alternatives\n→ fork_session per approach", shape=box, style="rounded,filled", fillcolor="#CCFBF1", color="#0D9488"];
  CRASH [label="⭐ a run crashed\n→ load the manifest,\nre-run only the unfinished", shape=box, style="rounded,filled", fillcolor="#D1FAE5", color="#059669"];
  DONE [label="A specific, current answer", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  CONTINUE [label="✗ --continue: the most\nrecent session, not the named one", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  SILENT [label="✗ resume without saying\nwhat changed → stale answer", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  REEXPLORE [label="✗ fresh with no summary\n→ full re-exploration", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  STALE [label="✗ resume a mostly-stale\nsession → degraded answer", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  NOFORK [label="✗ resume the same baseline\nfor both approaches", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  RESTART [label="✗ restart every agent\nafter the crash", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  START -> Q;
  Q -> NAMED; NAMED -> DONE;
  Q -> TELL; TELL -> DONE;
  Q -> FRESH; FRESH -> DONE;
  Q -> FORK; FORK -> DONE;
  Q -> CRASH; CRASH -> DONE;
  { rank=same; NAMED; TELL; } { rank=same; FRESH; } { rank=same; FORK; } { rank=same; CRASH; } NAMED -> FRESH [style=invis]; FRESH -> FORK [style=invis]; FORK -> CRASH [style=invis];
  { rank=same; CONTINUE; } { rank=same; SILENT; } { rank=same; REEXPLORE; } { rank=same; STALE; } { rank=same; NOFORK; } { rank=same; RESTART; } CONTINUE -> SILENT [style=invis]; SILENT -> REEXPLORE [style=invis]; REEXPLORE -> STALE [style=invis]; STALE -> NOFORK [style=invis]; NOFORK -> RESTART [style=invis];
  DONE -> CONTINUE [style=invis];
  KEY [shape=plain, label=<<TABLE BORDER="0" CELLBORDER="1" CELLSPACING="3" CELLPADDING="3"><TR><TD COLSPAN="2" BORDER="0" ALIGN="LEFT"><FONT POINT-SIZE="18"><B>Key</B></FONT></TD></TR><TR><TD BGCOLOR="#EDE9FE" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">the decision — how much of the old context is still true?</FONT></TD></TR><TR><TD BGCOLOR="#DBEAFE" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">resume (by name; tell it what changed)</FONT></TD></TR><TR><TD BGCOLOR="#FEF3C7" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">fresh start + structured summary / scratchpad / /compact</FONT></TD></TR><TR><TD BGCOLOR="#CCFBF1" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">branch with fork_session</FONT></TD></TR><TR><TD BGCOLOR="#D1FAE5" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">crash recovery from a manifest</FONT></TD></TR><TR><TD BGCOLOR="#FFFFFF" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">bug (an exam distractor)</FONT></TD></TR><TR><TD WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"><FONT POINT-SIZE="16">⭐</FONT></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">named by the exam guide (TS 1.7 pp.8–9, TS 5.4 pp.21–22)</FONT></TD></TR></TABLE>>];
  RESTART -> KEY [style=invis];
}

decisionDot:
digraph D {
  rankdir=TB; bgcolor="transparent"; nodesep=0.35; ranksep=0.4;
  node [fontname="Helvetica", fontsize=18, margin="0.2,0.1", style="rounded,filled", fillcolor="#F3F4F6", color="#9CA3AF", penwidth=1.5];
  edge [fontname="Helvetica", fontsize=16, penwidth=1.5, color="#6B7280"];
  Q0 [shape=diamond, label="Do you want to try\nmore than one direction?"];
  FORK [shape=box, fillcolor="#CCFBF1", color="#0D9488", label="Fork the baseline per direction\n(guide TS 1.7 K2, S2)"];
  Q1 [shape=diamond, label="How much of the earlier\ntool results is still true?"];
  RES [shape=box, fillcolor="#DBEAFE", color="#0066CC", label="All of it: --resume <name>\n(TS 1.7 K1, S1)"];
  TELL [shape=box, fillcolor="#DBEAFE", color="#0066CC", label="Mostly: resume + name the changed files\n(TS 1.7 K3, S4)"];
  FRESH [shape=box, fillcolor="#FEF3C7", color="#D97706", label="Little: new session + structured summary\n(TS 1.7 K4, S3)"];
  Q2 [shape=diamond, label="Session getting long,\nanswers turning vague?"];
  CMP [shape=box, fillcolor="#FEF3C7", color="#D97706", label="Scratchpad of key findings, /compact,\nsubagents for exploration (TS 5.4)"];
  Q0 -> FORK [label="yes"]; Q0 -> Q1 [label="no"];
  Q1 -> RES [label="all"]; Q1 -> TELL [label="mostly"]; Q1 -> FRESH [label="little"];
  RES -> Q2; TELL -> Q2; Q2 -> CMP [label="yes"];
  { rank=same; RES; TELL; } { rank=same; FRESH; } RES -> FRESH [style=invis];
}
